+bool remote_timing() {
+    static const bool on = [] { const char* v = std::getenv("STRATA_REMOTE_TIMING"); return v && v[0] == '1'; }();
+    return on;
+}
+
+// ---- the sockets of both systems behind one small set of calls
+#if defined(_WIN32)
+using sock_t = SOCKET;
